#include <stdio.h>
#include <string.h>

int main() {
    /* 长度不超过 100，数组要开到 101：
       字符串结尾还要额外放一个 '\0' 占位置 */
    char s[101];

    /* 数组名就是首地址，因此不用（也不该）加 & */
    scanf("%s", s);

    /* strlen 数的是「'\0' 之前有多少个字符」，
       结尾的 '\0' 自己不算长度 */
    printf("%d\n", (int)strlen(s));
    return 0;
}

