#include <stdio.h>

int main() {
    char s[101];
    scanf("%s", s);

    int count = 0;

    /* 循环的终点是结尾的 '\0'，而不是数组长度 101 */
    for (int i = 0; s[i] != '\0'; i++) {
        /* 数字字符的 ASCII 码是连续的，
           所以直接和 '0'、'9' 比大小就能判断 */
        if (s[i] >= '0' && s[i] <= '9') {
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}

