#include <stdio.h>

int main() {
    char s[101];
    scanf("%s", s);

    /* 就地修改数组里的每一个字符 */
    for (int i = 0; s[i] != '\0'; i++) {
        /* 只动小写字母：范围之外的一律不碰，
           否则数字和大写字母会被减成毫不相干的字符 */
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = s[i] - 'a' + 'A';
        }
    }

    /* %s 从开头一路打印到 '\0'，不用自己写循环输出 */
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    char s[101];
    scanf("%s", s);

    int n = (int)strlen(s);

    /* 首尾对称交换：i 和 n - 1 - i 是一对。
       只走到中间就停——继续走会把刚换好的又换回来 */
    for (int i = 0; i < n / 2; i++) {
        char t = s[i];          /* 交换三件套的顺序不能颠倒 */
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }

    printf("%s\n", s);
    return 0;
}

