#include <stdio.h>
#include <string.h>

int main() {
    char s[101];
    scanf("%s", s);

    int n = (int)strlen(s);
    int ok = 1;   /* 先假设是回文串，发现问题再改成 0 */

    /* 从两头往中间比：只要有一对不同，就能断定不是回文 */
    for (int i = 0; i < n / 2; i++) {
        if (s[i] != s[n - 1 - i]) {
            ok = 0;
            break;   /* 已经能确定答案，不用再往下比 */
        }
    }

    if (ok) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
    return 0;
}

