#include <stdio.h>
#include <string.h>

int main() {
    /* 拼接后的结果要放得下 a 和 b 两个串，外加一个 '\0'：
       50 + 50 + 1 = 101，这里开 128 更保险 */
    char a[128], b[64];
    scanf("%s %s", a, b);

    /* 1. 先把比较结果存下来再拼接。
          strcat 会改掉 a 的内容，顺序颠倒的话
          第二行比较的就不是「原来的 a」了 */
    int cmp = strcmp(a, b);

    /* 2. strcat 从 a 的 '\0' 位置接着往后写，
          所以 a 必须开得足够大，装不下会写坏别的内存 */
    strcat(a, b);
    printf("%s\n", a);

    /* 3. strcmp 返回 0 才代表内容完全相同，
          返回正数表示前面的串大，负数表示前面的串小 */
    if (cmp == 0) {
        printf("equal\n");
    } else if (cmp > 0) {
        printf("greater\n");
    } else {
        printf("less\n");
    }
    return 0;
}

